1	import Fastify from "fastify";
2	import { PrismaClient } from "@prisma/client";
3	import jwt from "jsonwebtoken";
4	import bcrypt from "bcryptjs";
5	import dotenv from "dotenv";
6	
7	dotenv.config();
8	
9	const prisma = new PrismaClient();
10	const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";
11	
12	// Fastify 타입 확장
13	declare module "fastify" {
14	  interface FastifyRequest {
15	    userId?: number;
16	  }
17	}
18	
19	// ──────────────────────────────────────────────────────────────
20	// 유틸리티 함수들
21	// ──────────────────────────────────────────────────────────────
22	
23	// 사용자 응답 포맷터
24	function formatUserResponse(user: any, token: string) {
25	  return {
26	    user: {
27	      username: user.username,
28	      email: user.email,
29	      bio: user.bio,
30	      image: user.image,
31	      token,
32	    },
33	  };
34	}
35	
36	// 아티클 응답 포맷터 (상세/즐겨찾기 — body 포함)
37	function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
38	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
39	  const { tags: _tags, ...rest } = article;
40	  return {
41	    ...rest,
42	    tagList: tags,
43	    favorited,
44	    favoritesCount,
45	  };
46	}
47	
48	// 아티클 응답 포맷터 (목록/피드 — body 제외)
49	function formatArticleListResponse(article: any, favorited: boolean, favoritesCount: number) {
50	  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
51	  const { body, tags: _tags, ...rest } = article;
52	  return {
53	    ...rest,
54	    tagList: tags,
55	    favorited,
56	    favoritesCount,
57	  };
58	}
59	
60	// 인증 미들웨어
61	async function authMiddleware(request: any, reply: any) {
62	  const authHeader = request.headers.authorization;
63	  if (!authHeader) {
64	    reply.code(401).send({ errors: { token: ["is missing"] } });
65	    return;
66	  }
67	  const parts = authHeader.split(" ");
68	  if (parts[0] !== "Token") {
69	    reply.code(401).send({ errors: { token: ["is invalid"] } });
70	    return;
71	  }
72	  try {
73	    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
74	    request.userId = decoded.id;
75	  } catch {
76	    reply.code(401).send({ errors: { token: ["is invalid"] } });
77	    return;
78	  }
79	}
80	
81	// 슬러그 생성 헬퍼
82	function generateSlug(title: string): string {
83	  return title.toLowerCase().replace(/\s+/g, "-");
84	}
85	
86	// ──────────────────────────────────────────────────────────────
87	// Fastify 앱 초기화
88	// ──────────────────────────────────────────────────────────────
89	
90	const app = Fastify({
91	  logger: true,
92	});
93	
94	// CORS 수동 설정
95	app.addHook("onRequest", async (request: any, reply: any) => {
96	  reply.header("Access-Control-Allow-Origin", "*");
97	  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
98	  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
99	  if (request.method === "OPTIONS") {
100	    reply.code(204).send();
101	    return;
102	  }
103	});
104	
105	// ──────────────────────────────────────────────────────────────
106	// 사용자 API
107	// ──────────────────────────────────────────────────────────────
108	
109	// 회원가입
110	app.post("/api/users", async (request: any, reply: any) => {
111	  const { username, email, password } = request.body?.user || {};
112	  if (!username || !email || !password) {
113	    const errs: Record<string, string[]> = {};
114	    if (!username) errs.username = ["can't be blank"];
115	    if (!email) errs.email = ["can't be blank"];
116	    if (!password) errs.password = ["can't be blank"];
117	    reply.code(422).send({ errors: errs });
118	    return;
119	  }
120	  const existing = await prisma.user.findFirst({
121	    where: { OR: [{ username }, { email }] },
122	  });
123	  if (existing) {
124	    const err: Record<string, string[]> = {};
125	    if (existing.username === username) err.username = ["has already been taken"];
126	    if (existing.email === email) err.email = ["has already been taken"];
127	    reply.code(409).send({ errors: err });
128	    return;
129	  }
130	  const hashedPassword = await bcrypt.hash(password, 10);
131	  const user = await prisma.user.create({
132	    data: { username, email, password: hashedPassword },
133	  });
134	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
135	  reply.code(201).send(formatUserResponse(user, token));
136	  return;
137	});
138	
139	// 로그인
140	app.post("/api/users/login", async (request: any, reply: any) => {
141	  const { email, password } = request.body?.user || {};
142	  if (!email || !password) {
143	    const errs: Record<string, string[]> = {};
144	    if (!email) errs.email = ["can't be blank"];
145	    if (!password) errs.password = ["can't be blank"];
146	    reply.code(422).send({ errors: errs });
147	    return;
148	  }
149	  const user = await prisma.user.findUnique({ where: { email: email as string } });
150	  if (!user || !(await bcrypt.compare(password, user.password))) {
151	    reply.code(401).send({ errors: { credentials: ["invalid"] } });
152	    return;
153	  }
154	  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
155	  reply.code(200).send(formatUserResponse(user, token));
156	  return;
157	});
158	
159	// 현재 사용자 조회
160	app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
161	  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
162	  const token = request.headers.authorization.split(" ")[1];
163	  return formatUserResponse(user, token);
164	});
