226	// 프로필 조회
227	app.get("/api/profiles/:username", async (request: any, reply: any) => {
228	  const username = request.params.username as string;
229	  const profile = await prisma.user.findUnique({
230	    where: { username },
231	    select: { id: true, username: true, bio: true, image: true },
232	  });
233	  if (!profile) {
234	    reply.code(404).send({ errors: { profile: ["not found"] } });
235	    return;
236	  }
237	
238	  // 팔로우 상태 확인 (인증된 경우)
239	  let following = false;
240	  const authHeader = request.headers.authorization;
241	  if (authHeader) {
242	    const parts = authHeader.split(" ");
243	    if (parts[0] === "Token") {
244	      try {
245	        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
246	        const follow = await prisma.follow.findUnique({
247	          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
248	        });
249	        following = !!follow;
250	      } catch {
251	        following = false;
252	      }
253	    }
254	  }
255	
256	  return { profile: { ...profile, following } };
257	});
