260	app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
261	  const username = request.params.username as string;
262	  const target = await prisma.user.findUnique({
263	    where: { username },
264	    select: { id: true },
265	  });
266	  if (!target) {
267	    reply.code(404).send({ errors: { profile: ["not found"] } });
268	    return;
269	  }
270	  if (target.id === request.userId) {
271	    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
272	    return;
273	  }
274	  await prisma.follow.upsert({
275	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
276	    create: { followerId: request.userId, followingId: target.id },
277	    update: {},
278	  });
279	  const profile = await prisma.user.findUnique({
280	    where: { username },
281	    select: { id: true, username: true, bio: true, image: true },
282	  });
283	  const isFollowing = await prisma.follow.findUnique({
284	    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
285	  });
286	  return { profile: { ...profile, following: !!isFollowing } };
287	});
