317	// 아티클 생성
318	app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
319	  const { title, description, body, tagList = [] } = request.body?.article || {};
320	  if (!title || !description || !body) {
321	    const errs: Record<string, string[]> = {};
322	    if (!title) errs.title = ["can't be blank"];
323	    if (!description) errs.description = ["can't be blank"];
324	    if (!body) errs.body = ["can't be blank"];
325	    reply.code(422).send({ errors: errs });
326	    return;
327	  }
328	  const slug = generateSlug(title);
329	  const article = await prisma.article.create({
330	    data: {
331	      slug,
332	      title,
333	      description,
334	      body,
335	      author: { connect: { id: request.userId } },
336	      tags: {
337	        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
338	      },
339	    },
340	    include: {
341	      author: { select: { username: true, bio: true, image: true } },
342	      tags: true,
343	      favorites: true,
344	    },
345	  });
346	  reply.code(201).send({
347	    article: formatArticleResponse(article, false, article.favorites.length),
348	  });
349	  return;
350	});
