352	// 아티클 목록 조회
353	app.get("/api/articles", async (request: any, reply: any) => {
354	  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
355	  const lim = parseInt(limit as string, 10);
356	  const off = parseInt(offset as string, 10);
357	
358	  const where: any = {};
359	  if (author) {
360	    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
361	    if (!user) {
362	      return { articles: [], articlesCount: 0 };
363	    }
364	    where.authorId = user.id;
365	  }
366	  if (tag) {
367	    where.tags = { some: { tag: (tag as string).toLowerCase() } };
368	  }
369	
370	  if (favorited) {
371	    const user = await prisma.user.findUnique({
372	      where: { username: favorited as string },
373	      select: { id: true },
374	    });
375	    if (!user) {
376	      return { articles: [], articlesCount: 0 };
377	    }
378	    const favorites = await prisma.favorite.findMany({
379	      where: { userId: user.id },
380	      select: { articleId: true },
381	    });
382	    const articleIds = favorites.map((f: any) => f.articleId);
383	    if (articleIds.length === 0) {
384	      return { articles: [], articlesCount: 0 };
385	    }
386	    const articles = await prisma.article.findMany({
387	      where: { id: { in: articleIds } },
388	      take: lim,
389	      skip: off,
390	      orderBy: { createdAt: "desc" },
391	      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
392	    });
393	    return {
394	      articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
395	      articlesCount: articles.length,
396	    };
397	  }
398	
399	  const articles = await prisma.article.findMany({
400	    where,
401	    take: lim,
402	    skip: off,
403	    orderBy: { createdAt: "desc" },
404	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
405	  });
406	  const articlesCount = await prisma.article.count({ where });
407	  return {
408	    articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
409	    articlesCount,
410	  };
411	});
