414	app.get("/api/articles/:slug", async (request: any, reply: any) => {
415	  const slug = request.params.slug as string;
416	  const article = await prisma.article.findUnique({
417	    where: { slug },
418	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
419	  });
420	  if (!article) {
421	    reply.code(404).send({ errors: { article: ["not found"] } });
