446	app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
447	  const slug = request.params.slug as string;
448	  const article = await prisma.article.findUnique({ where: { slug } });
449	  if (!article) {
450	    reply.code(404).send({ errors: { article: ["not found"] } });
451	    return;
452	  }
453	  if (article.authorId !== request.userId) {
454	    reply.code(403).send({ errors: { article: ["forbidden"] } });
455	    return;
456	  }
457	
458	  const body = request.body?.article || {};
459	  const updates: any = {};
460	  if (body.title !== undefined) updates.title = body.title;
461	  if (body.description !== undefined) updates.description = body.description;
462	  if (body.body !== undefined) updates.body = body.body;
463	
464	  // 태그 업데이트
465	  if (body.tagList !== undefined) {
466	    if (body.tagList === null) {
467	      reply.code(422).send({ errors: { article: ["tagList can't be blank"] } });
468	      return;
469	    }
470	    if (Array.isArray(body.tagList)) {
471	      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
472	      if (body.tagList.length > 0) {
473	        await prisma.articleTag.createMany({
474	          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
475	        });
476	      }
477	    }
478	  }
479	
480	  // 슬러그 업데이트
481	  if (updates.title) {
482	    updates.slug = generateSlug(updates.title);
483	  }
484	
485	  const updated = await prisma.article.update({
486	    where: { id: article.id },
487	    data: updates,
488	    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
489	  });
490	  return { article: formatArticleResponse(updated, false, updated.favorites.length) };
491	});
