576	// 코멘트 목록 조회
577	app.get("/api/articles/:slug/comments", async (request: any, reply: any) => {
578	  const slug = request.params.slug as string;
579	  const article = await prisma.article.findUnique({ where: { slug } });
580	  if (!article) {
581	    reply.code(404).send({ errors: { article: ["not found"] } });
582	    return;
