import Fastify from "fastify";
import { PrismaClient } from "@prisma/client";
import jwt from "jsonwebtoken";
import bcrypt from "bcryptjs";
import dotenv from "dotenv";

dotenv.config();

const prisma = new PrismaClient();
const JWT_SECRET = process.env.JWT_SECRET || "ralph-secret";

// Fastify 타입 확장
declare module "fastify" {
  interface FastifyRequest {
    userId?: number;
  }
}

// ──────────────────────────────────────────────────────────────
// 유틸리티 함수들
// ──────────────────────────────────────────────────────────────

// 사용자 응답 포맷터
function formatUserResponse(user: any, token: string) {
  return {
    user: {
      username: user.username,
      email: user.email,
      bio: user.bio,
      image: user.image,
      token,
    },
  };
}

// 아티클 응답 포맷터 (상세/즐겨찾기 — body 포함)
function formatArticleResponse(article: any, favorited: boolean, favoritesCount: number) {
  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
  const { tags: _tags, ...rest } = article;
  return {
    ...rest,
    tagList: tags,
    favorited,
    favoritesCount,
  };
}

// 아티클 응답 포맷터 (목록/피드 — body 제외)
function formatArticleListResponse(article: any, favorited: boolean, favoritesCount: number) {
  const tags: string[] = (article.tags || []).map((t: any) => t.tag);
  const { body, tags: _tags, ...rest } = article;
  return {
    ...rest,
    tagList: tags,
    favorited,
    favoritesCount,
  };
}

// 인증 미들웨어
async function authMiddleware(request: any, reply: any) {
  const authHeader = request.headers.authorization;
  if (!authHeader) {
    reply.code(401).send({ errors: { token: ["is missing"] } });
    return;
  }
  const parts = authHeader.split(" ");
  if (parts[0] !== "Token") {
    reply.code(401).send({ errors: { token: ["is invalid"] } });
    return;
  }
  try {
    const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
    request.userId = decoded.id;
  } catch {
    reply.code(401).send({ errors: { token: ["is invalid"] } });
    return;
  }
}

// 슬러그 생성 헬퍼
function generateSlug(title: string): string {
  return title.toLowerCase().replace(/\s+/g, "-");
}

// ──────────────────────────────────────────────────────────────
// Fastify 앱 초기화
// ──────────────────────────────────────────────────────────────

const app = Fastify({
  logger: true,
});

// CORS 수동 설정
app.addHook("onRequest", async (request: any, reply: any) => {
  reply.header("Access-Control-Allow-Origin", "*");
  reply.header("Access-Control-Allow-Methods", "GET, POST, PUT, DELETE, OPTIONS");
  reply.header("Access-Control-Allow-Headers", "Content-Type, Authorization");
  if (request.method === "OPTIONS") {
    reply.code(204).send();
    return;
  }
});

// ──────────────────────────────────────────────────────────────
// 사용자 API
// ──────────────────────────────────────────────────────────────

// 회원가입
app.post("/api/users", async (request: any, reply: any) => {
  const { username, email, password } = request.body?.user || {};
  if (!username || !email || !password) {
    const errs: Record<string, string[]> = {};
    if (!username) errs.username = ["can't be blank"];
    if (!email) errs.email = ["can't be blank"];
    if (!password) errs.password = ["can't be blank"];
    reply.code(422).send({ errors: errs });
    return;
  }
  const existing = await prisma.user.findFirst({
    where: { OR: [{ username }, { email }] },
  });
  if (existing) {
    const err: Record<string, string[]> = {};
    if (existing.username === username) err.username = ["has already been taken"];
    if (existing.email === email) err.email = ["has already been taken"];
    reply.code(409).send({ errors: err });
    return;
  }
  const hashedPassword = await bcrypt.hash(password, 10);
  const user = await prisma.user.create({
    data: { username, email, password: hashedPassword },
  });
  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
  reply.code(201).send(formatUserResponse(user, token));
  return;
});

// 로그인
app.post("/api/users/login", async (request: any, reply: any) => {
  const { email, password } = request.body?.user || {};
  if (!email || !password) {
    const errs: Record<string, string[]> = {};
    if (!email) errs.email = ["can't be blank"];
    if (!password) errs.password = ["can't be blank"];
    reply.code(422).send({ errors: errs });
    return;
  }
  const user = await prisma.user.findUnique({ where: { email: email as string } });
  if (!user || !(await bcrypt.compare(password, user.password))) {
    reply.code(401).send({ errors: { credentials: ["invalid"] } });
    return;
  }
  const token = jwt.sign({ id: user.id }, JWT_SECRET, { algorithm: "HS256" });
  reply.code(200).send(formatUserResponse(user, token));
  return;
});

// 현재 사용자 조회
app.get("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const user = await prisma.user.findUniqueOrThrow({ where: { id: request.userId } });
  const token = request.headers.authorization.split(" ")[1];
  return formatUserResponse(user, token);
});

// 사용자 정보 수정
app.put("/api/user", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const body = request.body?.user || {};
  const updates: any = {};
  if (body.username !== undefined) {
    if (body.username === "" || body.username === null) {
      reply.code(422).send({ errors: { username: ["can't be blank"] } });
      return;
    }
    updates.username = body.username;
  }
  if (body.email !== undefined) {
    if (body.email === "" || body.email === null) {
      reply.code(422).send({ errors: { email: ["can't be blank"] } });
      return;
    }
    updates.email = body.email;
  }
  if (body.bio !== undefined) updates.bio = body.bio === "" ? null : body.bio;
  if (body.image !== undefined) updates.image = body.image === "" ? null : body.image;
  if (body.password !== undefined) {
    if (body.password === "" || body.password === null || body.password.length < 8) {
      reply.code(422).send({ errors: { password: ["is too short (minimum is 8 characters)"] } });
      return;
    }
    updates.password = await bcrypt.hash(body.password, 10);
  }

  // 고유성 검증
  if (updates.username || updates.email) {
    const existing = await prisma.user.findFirst({
      where: {
        id: { not: request.userId },
        OR: [
          updates.username !== undefined ? { username: updates.username } : undefined,
          updates.email !== undefined ? { email: updates.email } : undefined,
        ].filter((e: any) => e !== undefined),
      },
    });
    if (existing) {
      const err: Record<string, string[]> = {};
      if (updates.username && existing.username === updates.username) err.username = ["has already been taken"];
      if (updates.email && existing.email === updates.email) err.email = ["has already been taken"];
      reply.code(422).send({ errors: err });
      return;
    }
  }

  const user = await prisma.user.update({
    where: { id: request.userId },
    data: updates,
  });
  const token = request.headers.authorization.split(" ")[1];
  return formatUserResponse(user, token);
});

// ──────────────────────────────────────────────────────────────
// 프로필 API
// ──────────────────────────────────────────────────────────────

// 프로필 조회
app.get("/api/profiles/:username", async (request: any, reply: any) => {
  const username = request.params.username as string;
  const profile = await prisma.user.findUnique({
    where: { username },
    select: { id: true, username: true, bio: true, image: true },
  });
  if (!profile) {
    reply.code(404).send({ errors: { profile: ["not found"] } });
    return;
  }

  // 팔로우 상태 확인 (인증된 경우)
  let following = false;
  const authHeader = request.headers.authorization;
  if (authHeader) {
    const parts = authHeader.split(" ");
    if (parts[0] === "Token") {
      try {
        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
        const follow = await prisma.follow.findUnique({
          where: { followerId_followingId: { followerId: decoded.id, followingId: profile.id } },
        });
        following = !!follow;
      } catch {
        following = false;
      }
    }
  }

  return { profile: { ...profile, following } };
});

// 팔로우
app.post("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const username = request.params.username as string;
  const target = await prisma.user.findUnique({
    where: { username },
    select: { id: true },
  });
  if (!target) {
    reply.code(404).send({ errors: { profile: ["not found"] } });
    return;
  }
  if (target.id === request.userId) {
    reply.code(422).send({ errors: { profile: ["can't follow yourself"] } });
    return;
  }
  await prisma.follow.upsert({
    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
    create: { followerId: request.userId, followingId: target.id },
    update: {},
  });
  const profile = await prisma.user.findUnique({
    where: { username },
    select: { id: true, username: true, bio: true, image: true },
  });
  const isFollowing = await prisma.follow.findUnique({
    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
  });
  return { profile: { ...profile, following: !!isFollowing } };
});

// 언팔로우
app.delete("/api/profiles/:username/follow", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const username = request.params.username as string;
  const target = await prisma.user.findUnique({
    where: { username },
    select: { id: true },
  });
  if (!target) {
    reply.code(404).send({ errors: { profile: ["not found"] } });
    return;
  }
  await prisma.follow.deleteMany({
    where: { followerId: request.userId, followingId: target.id },
  });
  const profile = await prisma.user.findUnique({
    where: { username },
    select: { id: true, username: true, bio: true, image: true },
  });
  const isFollowing = await prisma.follow.findUnique({
    where: { followerId_followingId: { followerId: request.userId, followingId: target.id } },
  });
  return { profile: { ...profile, following: !!isFollowing } };
});

// ──────────────────────────────────────────────────────────────
// 아티클 API
// ──────────────────────────────────────────────────────────────

// 아티클 생성
app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const { title, description, body, tagList = [] } = request.body?.article || {};
  if (!title || !description || !body) {
    const errs: Record<string, string[]> = {};
    if (!title) errs.title = ["can't be blank"];
    if (!description) errs.description = ["can't be blank"];
    if (!body) errs.body = ["can't be blank"];
    reply.code(422).send({ errors: errs });
    return;
  }
  const slug = generateSlug(title);
  const article = await prisma.article.create({
    data: {
      slug,
      title,
      description,
      body,
      author: { connect: { id: request.userId } },
      tags: {
        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
      },
    },
    include: {
      author: { select: { username: true, bio: true, image: true } },
      tags: true,
      favorites: true,
    },
  });
  reply.code(201).send({
    article: formatArticleResponse(article, false, article.favorites.length),
  });
  return;
});

// 아티클 목록 조회
app.get("/api/articles", async (request: any, reply: any) => {
  const { author, tag, favorited, limit = "20", offset = "0" } = request.query || {};
  const lim = parseInt(limit as string, 10);
  const off = parseInt(offset as string, 10);

  const where: any = {};
  if (author) {
    const user = await prisma.user.findUnique({ where: { username: author as string }, select: { id: true } });
    if (!user) {
      return { articles: [], articlesCount: 0 };
    }
    where.authorId = user.id;
  }
  if (tag) {
    where.tags = { some: { tag: (tag as string).toLowerCase() } };
  }

  if (favorited) {
    const user = await prisma.user.findUnique({
      where: { username: favorited as string },
      select: { id: true },
    });
    if (!user) {
      return { articles: [], articlesCount: 0 };
    }
    const favorites = await prisma.favorite.findMany({
      where: { userId: user.id },
      select: { articleId: true },
    });
    const articleIds = favorites.map((f: any) => f.articleId);
    if (articleIds.length === 0) {
      return { articles: [], articlesCount: 0 };
    }
    const articles = await prisma.article.findMany({
      where: { id: { in: articleIds } },
      take: lim,
      skip: off,
      orderBy: { createdAt: "desc" },
      include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
    });
    return {
      articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
      articlesCount: articles.length,
    };
  }

  const articles = await prisma.article.findMany({
    where,
    take: lim,
    skip: off,
    orderBy: { createdAt: "desc" },
    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
  });
  const articlesCount = await prisma.article.count({ where });
  return {
    articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
    articlesCount,
  };
});

// 아티클 상세 조회
app.get("/api/articles/:slug", async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const article = await prisma.article.findUnique({
    where: { slug },
    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
  });
  if (!article) {
    reply.code(404).send({ errors: { article: ["not found"] } });
    return;
  }
  // 즐겨찾기 여부 확인 (인증된 경우)
  let favorited = false;
  const authHeader = request.headers.authorization;
  if (authHeader) {
    const parts = authHeader.split(" ");
    if (parts[0] === "Token") {
      try {
        const decoded = jwt.verify(parts[1], JWT_SECRET) as { id: number };
        const fav = await prisma.favorite.findUnique({
          where: { userId_articleId: { userId: decoded.id, articleId: article.id } },
        });
        favorited = !!fav;
      } catch {
        favorited = false;
      }
    }
  }
  const favoritesCount = (article.favorites?.length) || 0;
  return { article: formatArticleResponse(article, favorited, favoritesCount) };
});

// 아티클 수정
app.put("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({ errors: { article: ["not found"] } });
    return;
  }
  if (article.authorId !== request.userId) {
    reply.code(403).send({ errors: { article: ["forbidden"] } });
    return;
  }

  const body = request.body?.article || {};
  const updates: any = {};
  if (body.title !== undefined) updates.title = body.title;
  if (body.description !== undefined) updates.description = body.description;
  if (body.body !== undefined) updates.body = body.body;

  // 태그 업데이트
  if (body.tagList !== undefined) {
    if (body.tagList === null) {
      reply.code(422).send({ errors: { article: ["tagList can't be blank"] } });
      return;
    }
    if (Array.isArray(body.tagList)) {
      await prisma.articleTag.deleteMany({ where: { articleId: article.id } });
      if (body.tagList.length > 0) {
        await prisma.articleTag.createMany({
          data: body.tagList.map((t: string) => ({ articleId: article.id, tag: t.toLowerCase() })),
        });
      }
    }
  }

  // 슬러그 업데이트
  if (updates.title) {
    updates.slug = generateSlug(updates.title);
  }

  const updated = await prisma.article.update({
    where: { id: article.id },
    data: updates,
    include: { author: { select: { username: true, bio: true, image: true } }, tags: true, favorites: true },
  });
  return { article: formatArticleResponse(updated, false, updated.favorites.length) };
});

// 아티클 삭제
app.delete("/api/articles/:slug", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({ errors: { article: ["not found"] } });
    return;
  }
  if (article.authorId !== request.userId) {
    reply.code(403).send({ errors: { article: ["forbidden"] } });
    return;
  }
  await prisma.article.delete({ where: { id: article.id } });
  reply.code(204).send();
  return;
});

// 아티클 피드
app.get("/api/articles/feed", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const { limit = "20", offset = "0" } = request.query || {};
  const lim = parseInt(limit as string, 10);
  const off = parseInt(offset as string, 10);

  const follows = await prisma.follow.findMany({
    where: { followerId: request.userId },
    select: { followingId: true },
  });
  const followingIds = follows.map((f: any) => f.followingId);

  let articles: any[];
  let articlesCount: number;

  if (followingIds.length === 0) {
    articles = [];
    articlesCount = 0;
  } else {
    articles = await prisma.article.findMany({
      where: { authorId: { in: followingIds } },
      take: lim,
      skip: off,
      orderBy: { createdAt: "desc" },
      include: {
        author: { select: { username: true, bio: true, image: true } },
        tags: true,
        favorites: true,
      },
    });
    articlesCount = await prisma.article.count({
      where: { authorId: { in: followingIds } },
    });
  }

  return {
    articles: articles.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
    articlesCount,
  };
});

// 코멘트 작성
app.post("/api/articles/:slug/comments", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const slug = request.params.slug as string;
  const article = await prisma.article.findUnique({ where: { slug } });
  if (!article) {
    reply.code(404).send({ errors: { article: ["not found"] } });
    return;
  }
  const { body } = request.body?.comment || {};
  if (!body) {
    reply.code(422).send({ errors: { body: ["can't be blank"] } });
    return;
  }
  const comment = await prisma.comment.create({
    data: {
      body,
      articleId: article.id,
      authorId: request.userId,
    },
    include: { author: { select: { username: true, bio: true, image: true } } },
  });
  reply.code(201).send({ comment });
  return;
});

