app.get("/api/tags", async (request: any, reply: any) => {
  const tags = await prisma.articleTag.findMany({
    select: { tag: true },
    distinct: ["tag"],
  });
  return { tags: tags.map((t) => t.tag) };
});

// ──────────────────────────────────────────────────────────────
// 전역 에러 핸들러
// ──────────────────────────────────────────────────────────────

app.setErrorHandler((error: any, request: any, reply: any) => {
  if (error.statusCode === 404) {
    reply.code(404).send({ errors: { message: ["not found"] } });
    return;
  }
  if (error.statusCode === 422) {
    reply.code(422).send(error.message ? { errors: { _message: [error.message] } } : error);
    return;
  }
  if (error.statusCode === 401) {
    reply.code(401).send(error.message ? { errors: { header: [error.message] } } : { errors: { header: ["인증이 필요합니다"] } });
    return;
  }
  request.log.error(error);
  reply.code(500).send({ errors: { message: ["서버 내부 오류가 발생했습니다"] } });
  return;
});

// ──────────────────────────────────────────────────────────────
// 서버 시작
// ──────────────────────────────────────────────────────────────

const start = async () => {
  try {
    const port = Number(process.env.PORT) || 3000;
    await app.listen({ port, host: "0.0.0.0" });
    app.log.info(`서버가 http://0.0.0.0:${port} 에서 실행 중입니다`);
  } catch (err) {
    app.log.error(err);
    process.exit(1);
  }
};

// Graceful shutdown
process.on("SIGINT", async () => {
  await prisma.$disconnect();
  process.exit(0);
});
process.on("SIGTERM", async () => {
  await prisma.$disconnect();
  process.exit(0);
});

start();

