  articles = await prisma.article.findMany({
    where: { authorId: { in: followingIds } },
    take: lim,
    skip: off,
    orderBy: { createdAt: "desc" },
    include: {
      author: { select: { id: true, username: true, bio: true, image: true } },
      tags: true,
      favorites: true,
    },
  });
  articlesCount = await prisma.article.count({
    where: { authorId: { in: followingIds } },
  });
}

const enriched = await Promise.all(
  articles.map(async (a: any) => {
    const author = a.author as { id: number; username: string; bio: string | null; image: string | null };
    const isFollowing = await prisma.follow.findUnique({
      where: { followerId_followingId: { followerId: request.userId, followingId: author.id } },
      select: { id: true },
    });
    return {
      ...a,
      author: { ...author, following: !!isFollowing },
    };
  }),
);
return {
  articles: enriched.map((a: any) => formatArticleListResponse(a, false, (a.favorites?.length) || 0)),
  articlesCount,
};

