// ──────────────────────────────────────────────────────────────

// 아티클 생성
app.post("/api/articles", { preHandler: authMiddleware }, async (request: any, reply: any) => {
  const { title, description, body, tagList = [] } = request.body?.article || {};
  if (!title || !description || !body) {
    const errs: Record<string, string[]> = {};
    if (!title) errs.title = ["can't be blank"];
    if (!description) errs.description = ["can't be blank"];
    if (!body) errs.body = ["can't be blank"];
    reply.code(422).send({ errors: errs });
    return;
  }
  const slug = generateSlug(title);
  const article = await prisma.article.create({
    data: {
      slug,
      title,
      description,
      body,
      author: { connect: { id: request.userId } },
      tags: {
        create: tagList.map((t: string) => ({ tag: t.toLowerCase() })),
      },
    },
    include: {
      author: { select: { username: true, bio: true, image: true } },
      tags: true,
      favorites: true,
    },

